import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"57、【巽】 巽下巽上","description":"子夏易傳 - 57、【巽】 巽下巽上","frontmatter":{"title":"57、【巽】 巽下巽上","description":"子夏易傳 - 57、【巽】 巽下巽上"},"headers":[],"relativePath":"classics/zixia/059.md","filePath":"classics/zixia/059.md"}'),i={name:"classics/zixia/059.md"};function r(_,p,c,o,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="_57、【巽】-巽下巽上" tabindex="-1">57、【巽】 巽下巽上 <a class="header-anchor" href="#_57、【巽】-巽下巽上" aria-label="Permalink to “57、【巽】 巽下巽上”">​</a></h1><p>卦辭：巽，小亨。利有攸往，利見大人。</p><p>彖曰：重巽以申命，剛巽乎中正而志行，柔皆順乎剛，是以小亨，利有攸往，利見大人。</p><p>子夏：巽剛巽柔，柔順剛也。申重也。上下皆巽，政之缺乗，其巽而重命，其治命行，則獲安矣。陽居於中正雖巽而志行也。柔皆上順於剛，物無逆者，可以行權而合法也。巽以申之復，其小康也。是以小亨巽而往無不利也。大人得於中正，利以見之，輔而行其制也。</p><p>象曰：隨風巽，君子以申命行事。</p><p>子夏：風巽，風相隨也。故君子申上之命，而從其事，率民以隨上，而民皆隨令也。</p><p>初六，進退，利武人之貞。</p><p>象曰：進退，志疑也。利武人之貞，志治也。</p><p>子夏：巽柔在下，而不能果決，進退者也。巽於始，申命行事之初也。利於勇而行之則正也。非暴也，志行其治者也。</p><p>九二，巽在床下，用史巫，紛若吉，無咎。</p><p>象曰：紛若之吉，得中也。</p><p>子夏：巽乎下也，而又隂居床下之巽，猶得其中。巽下通上方，於祭祀之用史巫，雖多於敬事，達其命不任於已，則吉也。</p><p>九三，頻巽吝。</p><p>象曰：頻巽之吝，志窮也。</p><p>子夏：處卦之髙，巽於下柔，求其巽而不獲，匪其中而莫正，以至於頻蹙憂嗟也。剛不能執志，而窮於巽，可惜也巳。</p><p>六四，悔亡，田獲三品。</p><p>象曰：田獲三品，有功也。</p><p>子夏：隂巽主也。為陽所巽，而順於陽，得位上奉而當之矣。臣而行事悔之道也。順而正之，何悔之有，故建功而田獲三品能歆其神人也。</p><p>九五，貞吉，悔亡。無不利，無初有終，先庚三日，後庚三日，吉。</p><p>象曰：九五之吉，位正中也。</p><p>子夏：以剛而巽於中正，巽而無違，中而不過，正而得當，以是申命牧下之功，何悔之有，何往不利。始而從之，政非自我，故無初矣。後獲其治，故有終也。甲者則事之首，庚者甲之中也。申重也。事中失而重之治也，則無世無之矣。主巽於臣，臣順於主，而為功也。當其殷巽於大彭、豕韋申之也，其在周巽於齊桓、晉文申之重，而其道小通矣。夫正其失者，先原其始，察其中知其弊，故先之三日也。因其弊而反正其失，得後三日之吉也。不可以不審也。無因而為者，未之有也。</p><p>上九，巽在床下，喪其資斧，貞兇。</p><p>象曰：巽在床下，上窮也。喪其資斧，正乎兇也。</p><p>子夏：以剛而居重巽之上，以巽於下，巽而極過，巽無甚焉，在床下者也。極巽失據，無剛之用，資器皆亡之矣，身將安守哉，正其兇也。</p>',24)])])}const f=a(i,[["render",r]]);export{m as __pageData,f as default};
